  diagnostics: [{ key: "name", label: "Diagnostics bundle" }, { key: "category", label: "Category" }, { key: "owner", label: "Owner" }, { key: "createdAt", label: "Created" }, { key: "status", label: "State" }],
  serviceReviews: [{ key: "title", label: "Service review" }, { key: "period", label: "Period" }, { key: "owner", label: "Owner" }, { key: "dueAt", label: "Due" }, { key: "status", label: "State" }],
