function Badge({ value }: { value?: string }) {
  const label = String(value || "unknown").toLowerCase();
  const style = label.includes("high") || label.includes("critical") || label.includes("at_risk") || label.includes("escalated") || label.includes("breached") ? "border-rose-400/25 bg-rose-500/10 text-rose-300" : label.includes("medium") || label.includes("attention") || label.includes("flagged") || label.includes("triaged") || label.includes("limited") || label.includes("watch") ? "border-amber-400/25 bg-amber-500/10 text-amber-200" : label.includes("resolved") || label.includes("healthy") || label.includes("active") || label.includes("completed") || label.includes("confirmed") || label.includes("low") ? "border-emerald-400/25 bg-emerald-500/10 text-emerald-200" : "border-slate-500/25 bg-slate-500/10 text-slate-300";
  return <span className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-1 text-[11px] font-semibold capitalize tracking-wide ${style}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{humanize(label)}</span>;
}

function PermissionNotice({ role, entity }: { role: string; entity: string }) { return <div className="flex items-start gap-3 rounded-xl border border-amber-400/20 bg-amber-400/[0.06] p-4"><span className="rounded-lg bg-amber-400/10 p-2 text-amber-200"><LockKeyhole className="h-4 w-4" /></span><div><p className="text-sm font-semibold text-amber-100">Read-only permission state</p><p className="mt-1 text-xs leading-5 text-amber-100/70">The current <strong className="capitalize">{role}</strong> profile can inspect {humanize(entity)} records but cannot change them. The desktop process will also deny unapproved requests.</p></div></div>; }

function TableShell({ children }: { children: React.ReactNode }) { return <div className="overflow-hidden rounded-2xl border border-slate-800 bg-[#111b2e] shadow-[0_14px_45px_rgba(0,0,0,0.16)]"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm">{children}</table></div></div>; }
function Empty({ title, detail }: { title: string; detail: string }) { return <div className="grid min-h-40 place-items-center p-7 text-center"><div><Search className="mx-auto h-5 w-5 text-slate-500" /><p className="mt-3 text-sm font-semibold text-slate-200">{title}</p><p className="mt-1 text-xs text-slate-500">{detail}</p></div></div>; }
function Progress({ value }: { value: number }) { const tone = value >= 90 ? "bg-emerald-400" : value >= 75 ? "bg-cyan-400" : value >= 60 ? "bg-amber-400" : "bg-rose-400"; return <div className="flex min-w-24 items-center gap-2"><div className="h-1.5 flex-1 overflow-hidden rounded-full bg-slate-800"><div className={`h-full rounded-full ${tone}`} style={{ width: `${Math.max(0, Math.min(value, 100))}%` }} /></div><span className="w-8 text-right text-xs text-slate-300">{value}%</span></div>; }

export function EnhancedDomainWorkspace({ module, state, metadata, search, setSearch, onCreate, onEdit, onDetail, onDelete, onExport, onImport }: { module: ModuleKey; state: OpsState; metadata: any; search: string; setSearch: (value: string) => void } & ActionProps) {
  const entity = metadata.entity as keyof OpsState; const source = (state[entity] || []) as OpsRecord[]; const editable = roles[state.currentUser.role]?.includes(String(entity)); const [field, setField] = useState("all"); const [value, setValue] = useState("all"); const [saved, setSaved] = useState<{ name: string; field: string; value: string; query: string }[]>([]);
  useEffect(() => { const raw = localStorage.getItem(`ops-views-${entity}`); if (raw) { try { setSaved(JSON.parse(raw)); } catch { setSaved([]); } } }, [entity]);
  const filterOptions = useMemo(() => { const preferred = entity === "students" ? ["cohort", "status", "risk", "program"] : entity === "instructors" ? ["specialty", "status"] : entity === "sessions" ? ["status", "course", "room"] : entity === "incidents" || entity === "anomalies" ? ["status", "severity", "domain"] : entity === "quality" ? ["status", "owner"] : entity === "kpis" ? ["domain", "owner"] : entity === "sops" ? ["domain", "incidentType"] : ["scope", "createdBy"]; return preferred.filter((key) => source.some((item) => item[key])); }, [entity, source]);
  useEffect(() => { if (field !== "all" && !filterOptions.includes(field)) { setField("all"); setValue("all"); } }, [field, filterOptions]);
  const values = field === "all" ? [] : Array.from(new Set(source.map((item) => String(item[field] || "Unspecified")))).sort();
  const rows = source.filter((item) => JSON.stringify(item).toLowerCase().includes(search.toLowerCase())).filter((item) => field === "all" || value === "all" || String(item[field] || "Unspecified") === value);
  const saveView = () => { const name = prompt("Name this view"); if (!name) return; const next = [...saved.filter((item) => item.name !== name), { name, field, value, query: search }]; setSaved(next); localStorage.setItem(`ops-views-${entity}`, JSON.stringify(next)); toast.success(`Saved view “${name}”.`); };
  const header = module === "kpis" ? "Metric governance" : module === "sops" ? "Operational knowledge" : module === "anomalies" || module === "incidents" ? "Evidence and workflow" : "Operational records";
  return <div className="space-y-6"><div className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-cyan-300">{header}</p><h1 className="mt-2 text-3xl font-semibold tracking-tight text-white">{metadata.title}</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-400">{metadata.description}</p></div><div className="flex flex-wrap gap-2">{module === "students" ? <Button variant="outline" onClick={onImport} className="h-9 border-slate-700 bg-[#111b2e] text-slate-300 hover:bg-slate-800 hover:text-white"><Upload className="mr-2 h-4 w-4" />Import CSV</Button> : null}<Button variant="outline" onClick={onExport} className="h-9 border-slate-700 bg-[#111b2e] text-slate-300 hover:bg-slate-800 hover:text-white"><Download className="mr-2 h-4 w-4" />Export</Button><Button onClick={onCreate} disabled={!editable} className="h-9 bg-cyan-400 text-slate-950 hover:bg-cyan-300 disabled:cursor-not-allowed disabled:opacity-40"><Plus className="mr-2 h-4 w-4" />{metadata.createLabel}</Button></div></div>{!editable ? <PermissionNotice role={state.currentUser.role} entity={String(entity)} /> : null}<div className="rounded-2xl border border-slate-800 bg-[#111b2e] p-3"><div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_150px_170px_auto]"><div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={`Search ${metadata.title.toLowerCase()}…`} className="h-10 border-slate-700 bg-slate-950/50 pl-9 text-slate-100 placeholder:text-slate-600" /></div><select value={field} onChange={(event) => { setField(event.target.value); setValue("all"); }} className="h-10 rounded-md border border-slate-700 bg-slate-950/50 px-3 text-sm text-slate-200"><option value="all">All fields</option>{filterOptions.map((item) => <option key={item} value={item}>{humanize(item)}</option>)}</select><select value={value} onChange={(event) => setValue(event.target.value)} disabled={field === "all"} className="h-10 rounded-md border border-slate-700 bg-slate-950/50 px-3 text-sm text-slate-200 disabled:opacity-50"><option value="all">All values</option>{values.map((item) => <option key={item} value={item}>{item}</option>)}</select><Button variant="outline" onClick={saveView} className="h-10 border-slate-700 bg-slate-950/30 text-slate-300 hover:bg-slate-800 hover:text-white"><Save className="mr-2 h-4 w-4" />Save view</Button></div>{saved.length ? <div className="mt-3 flex flex-wrap gap-2 border-t border-slate-800 pt-3"><span className="self-center text-[10px] font-bold uppercase tracking-[0.12em] text-slate-500">Saved views</span>{saved.map((view) => <button key={view.name} onClick={() => { setField(view.field); setValue(view.value); setSearch(view.query); }} className="rounded-md border border-slate-700 bg-slate-950/40 px-2.5 py-1.5 text-xs text-cyan-200 hover:border-cyan-300/30">{view.name}</button>)}</div> : null}<p className="mt-3 flex items-center gap-2 text-xs text-slate-500"><Filter className="h-3.5 w-3.5" />{rows.length} of {source.length} visible records</p></div>{module === "sops" ? <SopGrid items={rows} onDetail={onDetail} /> : module === "analyses" ? <AnalysisGrid items={rows} onDetail={onDetail} /> : <RecordTable entity={String(entity)} items={rows} editable={editable} onEdit={onEdit} onDetail={onDetail} onDelete={onDelete} />}</div>;
}

function RecordTable({ entity, items, editable, onEdit, onDetail, onDelete }: { entity: string; items: OpsRecord[]; editable: boolean; onEdit: (record: OpsRecord) => void; onDetail: (record: OpsRecord) => void; onDelete: (id: string) => void }) { const current = columns[entity] || []; const readOnlyHistory = entity === "analystRuns"; return <TableShell><thead className="border-b border-slate-800 bg-slate-950/30 text-[11px] uppercase tracking-[0.13em] text-slate-400"><tr>{current.map((column) => <th key={column.key} className="px-5 py-3.5 font-semibold">{column.label}</th>)}<th className="px-5 py-3.5 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-800">{items.length ? items.map((item) => <tr key={item.id} className="hover:bg-slate-800/25">{current.map((column) => <td key={column.key} className="px-5 py-4 text-sm text-slate-300">{["status", "risk", "severity", "priority", "outcome"].includes(column.key) ? <Badge value={item[column.key]} /> : column.key.endsWith("At") ? formatDate(item[column.key]) : ["progress", "attendance", "attendanceRate", "completeness", "accuracy", "freshness"].includes(column.key) ? <Progress value={Number(item[column.key] || 0)} /> : column.key === "rating" ? <span className="text-amber-200">★ {item[column.key]}</span> : column.key === "activeVersion" ? <span className="font-semibold text-cyan-200">v{item[column.key]}</span> : column.key === "target" || column.key === "warningThreshold" ? `${item[column.key]}${item.unit || ""}` : <span className="max-w-60 truncate font-medium text-slate-200">{item[column.key] || "—"}</span>}</td>)}<td className="px-5 py-4"><div className="flex justify-end gap-1"><button onClick={() => onDetail(item)} className="rounded-md p-2 text-slate-400 hover:bg-slate-800 hover:text-cyan-200" aria-label="View record"><Eye className="h-4 w-4" /></button><button onClick={() => onEdit(item)} disabled={!editable || readOnlyHistory} className="rounded-md p-2 text-slate-400 hover:bg-slate-800 hover:text-cyan-200 disabled:cursor-not-allowed disabled:opacity-35" aria-label={readOnlyHistory ? "Read-only evidence record" : "Edit record"}><Pencil className="h-4 w-4" /></button><button onClick={() => { if (confirm(`Delete this ${entity.slice(0, -1)}? The audit record will remain.`)) onDelete(item.id); }} disabled={!editable || readOnlyHistory} className="rounded-md p-2 text-slate-400 hover:bg-rose-500/10 hover:text-rose-200 disabled:cursor-not-allowed disabled:opacity-35" aria-label={readOnlyHistory ? "Read-only evidence record" : "Delete record"}><MoreHorizontal className="h-4 w-4" /></button></div></td></tr>) : <tr><td colSpan={current.length + 1}><Empty title="No matching records" detail="Try another filter, select a saved view, or create a record if your role permits it." /></td></tr>}</tbody></TableShell>; }
function SopGrid({ items, onDetail }: { items: OpsRecord[]; onDetail: (record: OpsRecord) => void }) { return <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{items.map((item) => <button key={item.id} onClick={() => onDetail(item)} className="rounded-2xl border border-slate-800 bg-[#111b2e] p-5 text-left transition hover:-translate-y-0.5 hover:border-cyan-300/30"><div className="flex items-start justify-between"><span className="rounded-xl bg-cyan-400/10 p-2.5 text-cyan-200"><BookOpen className="h-5 w-5" /></span><Badge value={`v${item.activeVersion}`} /></div><p className="mt-4 text-base font-semibold text-slate-100">{item.title}</p><p className="mt-1 text-xs text-slate-500">{item.domain}{item.incidentType ? ` · ${item.incidentType}` : ""}</p><p className="mt-4 line-clamp-3 text-sm leading-6 text-slate-400">{item.versions?.at(-1)?.body}</p><span className="mt-5 flex items-center gap-1 text-xs font-semibold text-cyan-300">Open version history <ChevronRight className="h-3.5 w-3.5" /></span></button>)}</div>; }
function AnalysisGrid({ items, onDetail }: { items: OpsRecord[]; onDetail: (record: OpsRecord) => void }) { return <div className="grid gap-4 lg:grid-cols-2">{items.map((item) => <button key={item.id} onClick={() => onDetail(item)} className="rounded-2xl border border-slate-800 bg-[#111b2e] p-5 text-left hover:border-cyan-300/30"><FileSearch className="h-5 w-5 text-indigo-200" /><p className="mt-4 text-base font-semibold text-slate-100">{item.name}</p><p className="mt-1 text-xs text-cyan-300">{item.scope} · {item.dataRange || "No range"}</p><p className="mt-4 line-clamp-3 text-sm leading-6 text-slate-400">{item.summary}</p></button>)}</div>; }

export function EnhancedDetailDrawer({ record, module, state, onClose, onUpdate, onSopVersion }: { record: OpsRecord | null; module: ModuleKey; state: OpsState; onClose: () => void; onUpdate: (entity: string, id: string, patch: OpsDraft) => Promise<void>; onSopVersion: (id: string, payload: OpsDraft) => Promise<void> }) {
  const [rootCause, setRootCause] = useState(""); const [note, setNote] = useState(""); const [resolution, setResolution] = useState(""); const [status, setStatus] = useState(""); const [versionBody, setVersionBody] = useState(""); const [versionSummary, setVersionSummary] = useState(""); const [issueTitle, setIssueTitle] = useState(""); const [issueAssignee, setIssueAssignee] = useState("");
  useEffect(() => { if (record) { setRootCause(record.rootCause || ""); setNote(record.note || ""); setResolution(record.resolution || ""); setStatus(record.status || ""); setVersionBody(""); setVersionSummary(""); setIssueTitle(""); setIssueAssignee(""); } }, [record]);
  if (!record) return null;
  if (module === "integrations" || module === "automations") return <EnterpriseExecutionDrawer record={record} module={module} state={state} onClose={onClose} />;
  if (module === "security") return <SecurityControlDrawer record={record} onClose={onClose} />;
  if (module === "diagnostics") return <DiagnosticsDrawer record={record} onClose={onClose} />;
  if (module === "reconciliations") return <ReconciliationDrawer record={record} onClose={onClose} />;
  if (module === "plans" || module === "dashboards" || module === "explorations") return <AnalyticsDrawer record={record} module={module} state={state} onClose={onClose} onUpdate={onUpdate} />;
  if (module === "serviceReviews") return <ServiceReviewDrawer record={record} onClose={onClose} onUpdate={onUpdate} />;
  const detailEntity = module === "organization" ? "organizationSettings" : module;
  const editable = roles[state.currentUser.role]?.includes(detailEntity);
  const studentMilestones = module === "students" ? record.milestones || [] : [];
  const instructorIncidents = module === "instructors" ? state.incidents.filter((item) => item.instructorId === record.id || item.assignee === record.name) : [];
  const auditTrail = state.audit.filter((entry) => entry.entityId === record.id).slice(0, 8);
  const saveInvestigation = async () => { try { await onUpdate(module, record.id, { status, rootCause, note, resolution }); toast.success("Investigation saved and audited."); } catch (error: any) { toast.error(error.message || "Could not save investigation."); } };
  const addIssue = async () => { if (!issueTitle.trim()) return; const issues = [...(record.issues || []), { title: issueTitle.trim(), severity: "medium", state: "open", assignee: issueAssignee || state.currentUser.name, remediation: "Define remediation action." }]; await onUpdate("quality", record.id, { issues }); setIssueTitle(""); setIssueAssignee(""); toast.success("Data quality issue logged and audited."); };
  if (["onboarding", "imports", "reports"].includes(module)) return <ExecutionDrawer record={record} module={module} state={state} onClose={onClose} onUpdate={onUpdate} editable={Boolean(editable)} />;
  return <aside className="fixed inset-y-0 right-0 z-40 flex w-full max-w-xl flex-col border-l border-slate-700 bg-[#101827] shadow-[-22px_0_65px_rgba(0,0,0,0.45)]"><div className="flex items-start justify-between border-b border-slate-800 px-6 py-5"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-cyan-300">{module === "anomalies" ? "Investigation workspace" : `${humanize(module)} detail`}</p><h2 className="mt-1 text-xl font-semibold text-white">{record.name || record.title || record.domain}</h2><div className="mt-2"><Badge value={record.status || record.severity || "active"} /></div></div><button onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-slate-800 hover:text-white" aria-label="Close detail"><X className="h-5 w-5" /></button></div><div className="flex-1 overflow-y-auto px-6 py-5"><section className="grid gap-3 sm:grid-cols-2">{Object.entries(record).filter(([key, value]) => !["id", "rootCause", "note", "resolution", "context", "versions", "actuals", "issues", "milestones", "provenance"].includes(key) && typeof value !== "object").map(([key, value]) => <div key={key} className="rounded-xl border border-slate-800 bg-slate-950/25 p-3"><p className="text-[10px] font-bold uppercase tracking-[0.12em] text-slate-500">{humanize(key)}</p><p className="mt-1.5 break-words text-sm text-slate-200">{key.includes("At") ? formatDate(String(value)) : String(value || "—")}</p></div>)}</section>{!editable ? <div className="mt-5"><PermissionNotice role={state.currentUser.role} entity={module} /></div> : null}{studentMilestones.length ? <section className="mt-5 rounded-xl border border-slate-800 bg-slate-950/25 p-4"><div className="flex items-center gap-2"><GraduationCap className="h-4 w-4 text-cyan-200" /><p className="text-sm font-semibold text-slate-100">Progress milestones</p></div><ol className="mt-3 space-y-2">{studentMilestones.map((milestone: string, index: number) => <li key={milestone} className="flex items-center gap-2 text-sm text-slate-300"><span className="grid h-5 w-5 place-items-center rounded-full bg-cyan-400/10 text-[10px] font-bold text-cyan-200">{index + 1}</span>{milestone}</li>)}</ol></section> : null}{instructorIncidents.length ? <section className="mt-5 rounded-xl border border-slate-800 bg-slate-950/25 p-4"><div className="flex items-center gap-2"><History className="h-4 w-4 text-cyan-200" /><p className="text-sm font-semibold text-slate-100">Linked incident history</p></div><div className="mt-3 space-y-2">{instructorIncidents.map((incident) => <div key={incident.id} className="rounded-lg border border-slate-800 p-3"><div className="flex items-center justify-between gap-2"><p className="text-sm font-medium text-slate-200">{incident.title}</p><Badge value={incident.status} /></div><p className="mt-1 text-xs text-slate-500">{humanize(incident.severity)} severity · {humanize(incident.type)}</p></div>)}</div></section> : null}{record.context ? <section className="mt-5 rounded-xl border border-cyan-400/15 bg-cyan-400/[0.05] p-4"><p className="text-xs font-semibold uppercase tracking-[0.12em] text-cyan-200">Drill-down evidence context</p><p className="mt-2 text-sm leading-6 text-slate-300">{record.context}</p></section> : null}{["anomalies", "incidents"].includes(module) ? <section className="mt-5 space-y-4 rounded-xl border border-slate-800 bg-slate-950/25 p-4"><div className="flex items-center gap-2"><ClipboardCheck className="h-4 w-4 text-cyan-300" /><p className="text-sm font-semibold text-slate-100">Decision and investigation record</p></div><p className="text-xs leading-5 text-slate-400">Retrieved facts, analyst interpretation, and next actions remain distinct. Every save appends audit evidence.</p><select value={status} onChange={(event) => setStatus(event.target.value)} disabled={!editable} className="h-10 w-full rounded-md border border-slate-700 bg-slate-950 px-3 text-sm text-slate-100 disabled:opacity-50"><option value="new">New</option><option value="flagged">Flagged</option><option value="triaged">Triaged</option><option value="investigating">Investigating</option><option value="escalated">Escalated</option><option value="resolved">Resolved</option><option value="dismissed">Dismissed</option></select><Textarea value={rootCause} onChange={(event) => setRootCause(event.target.value)} disabled={!editable} placeholder="Root-cause notes" className="min-h-20 border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" />{module === "anomalies" ? <Textarea value={note} onChange={(event) => setNote(event.target.value)} disabled={!editable} placeholder="Evidence note" className="min-h-20 border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /> : null}<Textarea value={resolution} onChange={(event) => setResolution(event.target.value)} disabled={!editable} placeholder="Resolution or next action" className="min-h-20 border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /><Button onClick={saveInvestigation} disabled={!editable} className="w-full bg-cyan-400 text-slate-950 hover:bg-cyan-300 disabled:opacity-40">Save investigation update</Button></section> : null}{module === "quality" ? <section className="mt-5 space-y-3 rounded-xl border border-slate-800 bg-slate-950/25 p-4"><div className="flex items-center gap-2"><Database className="h-4 w-4 text-cyan-200" /><p className="text-sm font-semibold text-slate-100">Issues and remediation</p></div>{(record.issues || []).length ? (record.issues || []).map((issue: any, index: number) => <div key={`${issue.title}-${index}`} className="rounded-lg border border-slate-800 p-3"><div className="flex items-center justify-between gap-2"><p className="text-sm font-medium text-slate-200">{issue.title}</p><select value={issue.state || "open"} disabled={!editable} onChange={async (event) => { const issues = (record.issues || []).map((item: any, itemIndex: number) => itemIndex === index ? { ...item, state: event.target.value } : item); await onUpdate("quality", record.id, { issues }); toast.success("Remediation progress updated."); }} className="h-8 rounded-md border border-slate-700 bg-slate-950 px-2 text-xs text-slate-200 disabled:opacity-50"><option value="open">Open</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option></select></div><p className="mt-1 text-xs text-slate-500">Owner: {issue.assignee || record.owner || "Unassigned"} · {humanize(issue.severity || "low")}</p><p className="mt-2 text-xs leading-5 text-slate-400">{issue.remediation}</p></div>) : <p className="text-xs text-slate-500">No remediation issues are logged for this domain.</p>}<div className="grid gap-2 border-t border-slate-800 pt-3"><Input value={issueTitle} onChange={(event) => setIssueTitle(event.target.value)} disabled={!editable} placeholder="Log remediation issue" className="border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /><Input value={issueAssignee} onChange={(event) => setIssueAssignee(event.target.value)} disabled={!editable} placeholder="Assign owner" className="border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /><Button onClick={addIssue} disabled={!editable || !issueTitle.trim()} className="bg-cyan-400 text-slate-950 hover:bg-cyan-300 disabled:opacity-40"><Plus className="mr-2 h-4 w-4" />Log remediation issue</Button></div></section> : null}{module === "sops" ? <section className="mt-5 space-y-4 rounded-xl border border-slate-800 bg-slate-950/25 p-4"><div className="flex items-center justify-between"><p className="text-sm font-semibold text-slate-100">Version history</p><Badge value={`v${record.activeVersion}`} /></div>{(record.versions || []).slice().reverse().map((version: any) => <div key={version.version} className="rounded-lg border border-slate-800 p-3"><p className="text-xs font-semibold text-cyan-200">Version {version.version} · {version.createdBy}</p><p className="mt-1 text-xs text-slate-500">{formatDate(version.createdAt)} · {version.summary}</p><p className="mt-2 text-sm leading-6 text-slate-300">{version.body}</p></div>)}<Textarea value={versionBody} onChange={(event) => setVersionBody(event.target.value)} disabled={!editable} placeholder="Revised procedure body" className="min-h-24 border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /><Input value={versionSummary} onChange={(event) => setVersionSummary(event.target.value)} disabled={!editable} placeholder="Version change summary" className="border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /><Button onClick={async () => { await onSopVersion(record.id, { body: versionBody, summary: versionSummary }); setVersionBody(""); setVersionSummary(""); toast.success("SOP version published."); }} disabled={!editable || !versionBody.trim()} className="bg-cyan-400 text-slate-950 hover:bg-cyan-300 disabled:opacity-40"><FileClock className="mr-2 h-4 w-4" />Publish new version</Button></section> : null}{module === "analyses" ? <section className="mt-5 rounded-xl border border-slate-800 bg-slate-950/25 p-4"><p className="text-sm font-semibold text-slate-100">Provenance and data range</p><p className="mt-2 text-xs leading-5 text-slate-400">Parameters: {record.parameters || "Not recorded"}</p><p className="mt-1 text-xs leading-5 text-slate-400">Range: {record.dataRange || "Not recorded"}</p><div className="mt-3 flex flex-wrap gap-1.5">{(record.provenance || []).map((source: string) => <span key={source} className="rounded-md border border-slate-700 bg-slate-900 px-2 py-1 text-[10px] text-cyan-200">{source}</span>)}</div></section> : null}{auditTrail.length ? <section className="mt-5 rounded-xl border border-slate-800 bg-slate-950/25 p-4"><div className="flex items-center gap-2"><Clock3 className="h-4 w-4 text-cyan-200" /><p className="text-sm font-semibold text-slate-100">Attributable event timeline</p></div><ol className="mt-3 space-y-3 border-l border-slate-700 pl-4">{auditTrail.map((entry) => <li key={entry.id} className="relative"><span className="absolute -left-[21px] top-1 h-2.5 w-2.5 rounded-full border-2 border-[#101827] bg-cyan-300" /><p className="text-xs font-semibold text-slate-200">{humanize(entry.action)}</p><p className="mt-0.5 text-xs text-slate-500">{formatDate(entry.timestamp)} · {entry.userName}</p><p className="mt-1 text-xs leading-5 text-slate-400">{entry.summary}</p></li>)}</ol></section> : null}</div></aside>;
}

function ExecutionDrawer({ record, module, state, onClose, onUpdate, editable }: { record: OpsRecord; module: ModuleKey; state: OpsState; onClose: () => void; onUpdate: (entity: string, id: string, patch: OpsDraft) => Promise<void>; editable: boolean }) {
  const [evidence, setEvidence] = useState(""); const [schedule, setSchedule] = useState(record.schedule || ""); const audit = state.audit.filter((entry) => entry.entityId === record.id).slice(0, 8);
  const completeChecklistItem = async (item: any, completed: boolean) => { const items = (record.items || []).map((entry: any) => entry.id === item.id ? { ...entry, completed, evidence: completed ? (evidence.trim() || entry.evidence || "Completion confirmed in the desktop workspace.") : "" } : entry); const done = items.length > 0 && items.every((entry: any) => entry.completed || !entry.required); await onUpdate("onboarding", record.id, { items, status: done ? "complete" : "in_progress" }); setEvidence(""); toast.success(completed ? "Checklist item completed and audited." : "Checklist item reopened and audited."); };
  const generateSnapshot = async () => { if (!window.desktopAPI) { toast.error("Run the Windows desktop app to generate a persisted report snapshot."); return; } try { await window.desktopAPI.generateReportSnapshot(record.id, schedule); window.dispatchEvent(new Event("ops-state-updated")); toast.success("Report snapshot generated from live workspace data and audited."); onClose(); } catch (error: any) { toast.error(error.message || "Could not generate report snapshot."); } };
  const saveRemediation = async () => { const run = (record.runs || [])[0]; if (!run) return; if (!evidence.trim()) { toast.error("Enter remediation evidence before recording the action."); return; } if (!window.desktopAPI) { toast.error("Run the Windows desktop app to persist remediation evidence."); return; } try { await window.desktopAPI.resolveImportRun(record.id, run.id, evidence); window.dispatchEvent(new Event("ops-state-updated")); setEvidence(""); toast.success("Import-run remediation recorded and audited."); onClose(); } catch (error: any) { toast.error(error.message || "Could not record import remediation."); } };
  const title = record.name || record.title || record.key || "Operational record";
  if (String(module) === "reports") return <ReportExecutionDrawer record={record} state={state} onClose={onClose} editable={editable} />;
  return <aside className="fixed inset-y-0 right-0 z-40 flex w-full max-w-xl flex-col border-l border-slate-700 bg-[#101827] shadow-[-22px_0_65px_rgba(0,0,0,0.45)]"><div className="flex items-start justify-between border-b border-slate-800 px-6 py-5"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-cyan-300">{humanize(module)} execution workspace</p><h2 className="mt-1 text-xl font-semibold text-white">{title}</h2><div className="mt-2"><Badge value={record.status || "active"} /></div></div><button onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-slate-800 hover:text-white" aria-label="Close detail"><X className="h-5 w-5" /></button></div><div className="flex-1 space-y-5 overflow-y-auto px-6 py-5">{!editable ? <PermissionNotice role={state.currentUser.role} entity={module} /> : null}{module === "onboarding" ? <section className="rounded-xl border border-slate-800 bg-slate-950/25 p-4"><p className="text-sm font-semibold text-slate-100">Activation checklist for {humanize(record.role || "operator")}</p><p className="mt-1 text-xs leading-5 text-slate-500">Complete mandatory checks with evidence before assigning this role to live operational work.</p><Textarea value={evidence} onChange={(event) => setEvidence(event.target.value)} disabled={!editable} placeholder="Completion evidence for the selected checklist item" className="mt-4 min-h-20 border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /><div className="mt-4 space-y-2">{(record.items || []).map((item: any) => <div key={item.id} className="flex items-start gap-3 rounded-lg border border-slate-800 p-3"><button disabled={!editable} onClick={() => completeChecklistItem(item, !item.completed)} className={`mt-0.5 grid h-5 w-5 place-items-center rounded border ${item.completed ? "border-emerald-300 bg-emerald-400 text-slate-950" : "border-slate-600 bg-slate-950 text-transparent"}`} aria-label={`${item.completed ? "Reopen" : "Complete"} ${item.label}`}><CheckCircle2 className="h-3.5 w-3.5" /></button><div className="min-w-0 flex-1"><p className={`text-sm ${item.completed ? "text-slate-400 line-through" : "text-slate-200"}`}>{item.label}{item.required ? <span className="ml-1 text-rose-300">*</span> : null}</p>{item.evidence ? <p className="mt-1 text-xs text-slate-500">Evidence: {item.evidence}</p> : null}</div></div>)}</div></section> : null}{module === "reports" ? <section className="space-y-4 rounded-xl border border-slate-800 bg-slate-950/25 p-4"><div><p className="text-sm font-semibold text-slate-100">Report execution and snapshot history</p><p className="mt-1 text-xs text-slate-500">Definitions, parameters, and every generated local snapshot remain attributable.</p></div><Input value={schedule} onChange={(event) => setSchedule(event.target.value)} disabled={!editable} placeholder="Scheduled-export readiness or cadence" className="border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /><Button onClick={generateSnapshot} disabled={!editable} className="w-full bg-cyan-400 text-slate-950 hover:bg-cyan-300 disabled:opacity-40"><FileClock className="mr-2 h-4 w-4" />Generate report snapshot</Button>{(record.snapshots || []).length ? <div className="space-y-2">{[...(record.snapshots || [])].reverse().map((snapshot: any) => <div key={snapshot.id} className="rounded-lg border border-slate-800 p-3"><div className="flex items-center justify-between gap-2"><p className="text-sm font-medium text-slate-200">{formatDate(snapshot.generatedAt)}</p><Badge value={snapshot.status} /></div><p className="mt-1 text-xs text-slate-500">{snapshot.rowCount} rows · {snapshot.summary}</p></div>)}</div> : <p className="text-xs text-slate-500">No snapshots generated yet.</p>}</section> : null}{module === "imports" ? <section className="space-y-4 rounded-xl border border-slate-800 bg-slate-950/25 p-4"><div><p className="text-sm font-semibold text-slate-100">Validation preview and import-run history</p><p className="mt-1 text-xs text-slate-500">Review mappings and failed-row evidence before recording remediation or allowing the next run.</p></div>{(record.runs || []).map((run: any) => <div key={run.id} className="rounded-lg border border-slate-800 p-3"><div className="flex items-center justify-between gap-2"><p className="text-sm font-medium text-slate-200">Run {formatDate(run.startedAt)}</p><Badge value={run.status} /></div><p className="mt-1 text-xs text-slate-500">Received {run.received} · Created {run.created} · Duplicates {run.duplicates} · Failed {run.failed}</p><ul className="mt-2 list-disc space-y-1 pl-4 text-xs leading-5 text-slate-400">{(run.preview || []).map((entry: string) => <li key={entry}>{entry}</li>)}</ul>{run.remediation ? <p className="mt-2 text-xs text-cyan-200">Remediation: {run.remediation}</p> : null}</div>)}<Textarea value={evidence} onChange={(event) => setEvidence(event.target.value)} disabled={!editable} placeholder="Failed-row remediation evidence or next source action" className="min-h-20 border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /><Button onClick={saveRemediation} disabled={!editable || !(record.runs || []).length} className="w-full bg-cyan-400 text-slate-950 hover:bg-cyan-300 disabled:opacity-40">Record remediation action</Button></section> : null}{audit.length ? <section className="rounded-xl border border-slate-800 bg-slate-950/25 p-4"><div className="flex items-center gap-2"><Clock3 className="h-4 w-4 text-cyan-200" /><p className="text-sm font-semibold text-slate-100">Attributable event timeline</p></div><div className="mt-3 space-y-3">{audit.map((entry) => <div key={entry.id} className="border-l border-slate-700 pl-3"><p className="text-xs font-semibold text-slate-200">{humanize(entry.action)}</p><p className="text-xs text-slate-500">{formatDate(entry.timestamp)} · {entry.userName}</p><p className="mt-1 text-xs text-slate-400">{entry.summary}</p></div>)}</div></section> : null}</div></aside>;
}

function ReportExecutionDrawer({ record, state, onClose, editable }: { record: OpsRecord; state: OpsState; onClose: () => void; editable: boolean }) {
  function SnapshotView() {
    const [scheduleValue, setScheduleValue] = useState(record.schedule || ""); const snapshots = [...(record.snapshots || [])].reverse(); const runs = [...(record.runHistory || [])].reverse();
    const generateRun = async () => { if (!window.desktopAPI) { toast.error("Run the Windows desktop app to generate a persisted report run."); return; } try { await window.desktopAPI.generateReportSnapshot(record.id, scheduleValue); window.dispatchEvent(new Event("ops-state-updated")); toast.success("Live report result, snapshot, and revisioned run history recorded."); onClose(); } catch (error: any) { toast.error(error.message || "Could not generate report run."); } };
    return <aside className="fixed inset-y-0 right-0 z-40 flex w-full max-w-xl flex-col border-l border-slate-700 bg-[#101827] shadow-[-22px_0_65px_rgba(0,0,0,0.45)]"><div className="flex items-start justify-between border-b border-slate-800 px-6 py-5"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-cyan-300">Report execution workspace</p><h2 className="mt-1 text-xl font-semibold text-white">{record.name}</h2><p className="mt-1 text-xs text-cyan-200">Current definition revision {record.definitionRevision || 1}</p></div><button onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-slate-800 hover:text-white" aria-label="Close detail"><X className="h-5 w-5" /></button></div><div className="flex-1 space-y-5 overflow-y-auto px-6 py-5"><section className="rounded-xl border border-slate-800 bg-slate-950/25 p-4"><p className="text-sm font-semibold text-slate-100">Scheduled-export readiness</p><Input value={scheduleValue} onChange={(event) => setScheduleValue(event.target.value)} disabled={!editable} className="mt-3 border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /><Button onClick={generateRun} disabled={!editable} className="mt-3 w-full bg-cyan-400 text-slate-950 hover:bg-cyan-300 disabled:opacity-40"><FileClock className="mr-2 h-4 w-4" />Generate live report run</Button></section><section className="rounded-xl border border-slate-800 bg-slate-950/25 p-4"><p className="text-sm font-semibold text-slate-100">Generated snapshots</p><div className="mt-3 space-y-2">{snapshots.length ? snapshots.map((snapshot: any) => <div key={snapshot.id} className="rounded-lg border border-slate-800 p-3"><div className="flex items-center justify-between gap-2"><p className="text-sm font-medium text-slate-200">{formatDate(snapshot.generatedAt)}</p><Badge value={snapshot.status} /></div><p className="mt-1 text-xs text-cyan-200">Definition revision {snapshot.definitionRevision || 1} · {snapshot.rowCount} result rows</p><p className="mt-1 text-xs text-slate-400">Parameters: {snapshot.parameters || "None"}</p><p className="mt-1 text-xs leading-5 text-slate-400">{snapshot.summary}</p></div>) : <p className="text-xs text-slate-500">No snapshots generated yet.</p>}</div></section><section className="rounded-xl border border-slate-800 bg-slate-950/25 p-4"><p className="text-sm font-semibold text-slate-100">Revisioned run history</p><div className="mt-3 space-y-2">{runs.length ? runs.map((run: any) => <div key={run.id} className="rounded-lg border border-slate-800 p-3"><p className="text-sm font-medium text-slate-200">{formatDate(run.generatedAt)} · revision {run.definitionRevision || 1}</p><p className="mt-1 text-xs text-slate-400">{run.rowCount} rows · {run.summary}</p></div>) : <p className="text-xs text-slate-500">No report run has been recorded.</p>}</div></section></div></aside>;
  }
  return <SnapshotView />;
  const [schedule, setSchedule] = useState(record.schedule || "");
  const generate = async () => { if (!window.desktopAPI) { toast.error("Run the Windows desktop app to generate a persisted report run."); return; } try { await window.desktopAPI.generateReportSnapshot(record.id, schedule); window.dispatchEvent(new Event("ops-state-updated")); toast.success("Live report result and revisioned run history recorded."); onClose(); } catch (error: any) { toast.error(error.message || "Could not generate report run."); } };
  const runs = [...(record.runHistory || [])].reverse();
  return <aside className="fixed inset-y-0 right-0 z-40 flex w-full max-w-xl flex-col border-l border-slate-700 bg-[#101827] shadow-[-22px_0_65px_rgba(0,0,0,0.45)]"><div className="flex items-start justify-between border-b border-slate-800 px-6 py-5"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-cyan-300">Report execution workspace</p><h2 className="mt-1 text-xl font-semibold text-white">{record.name}</h2><p className="mt-1 text-xs text-cyan-200">Definition revision {record.definitionRevision || 1}</p></div><button onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-slate-800 hover:text-white" aria-label="Close detail"><X className="h-5 w-5" /></button></div><div className="flex-1 space-y-5 overflow-y-auto px-6 py-5"><section className="rounded-xl border border-slate-800 bg-slate-950/25 p-4"><p className="text-sm font-semibold text-slate-100">Scheduled-export readiness</p><p className="mt-1 text-xs text-slate-500">The saved cadence is captured with the next server-side run. Background scheduling requires managed runtime infrastructure.</p><Input value={schedule} onChange={(event) => setSchedule(event.target.value)} disabled={!editable} className="mt-3 border-slate-700 bg-slate-950 text-slate-100 disabled:opacity-50" /><Button onClick={generate} disabled={!editable} className="mt-3 w-full bg-cyan-400 text-slate-950 hover:bg-cyan-300 disabled:opacity-40"><FileClock className="mr-2 h-4 w-4" />Generate live report run</Button></section><section className="rounded-xl border border-slate-800 bg-slate-950/25 p-4"><p className="text-sm font-semibold text-slate-100">Revisioned run history</p><div className="mt-3 space-y-2">{runs.length ? runs.map((run: any) => <div key={run.id} className="rounded-lg border border-slate-800 p-3"><div className="flex items-center justify-between gap-2"><p className="text-sm font-medium text-slate-200">{formatDate(run.generatedAt)}</p><Badge value={run.status} /></div><p className="mt-1 text-xs text-cyan-200">Definition revision {run.definitionRevision || 1} · {run.rowCount} result rows</p><p className="mt-1 text-xs leading-5 text-slate-400">Parameters: {run.parameters || "None"}</p><p className="mt-1 text-xs leading-5 text-slate-400">{run.summary}</p></div>) : <p className="text-xs text-slate-500">No generated runs yet.</p>}</div></section></div></aside>;
}
